import * as THREE from "three";
const scene=new THREE.Scene();
const camera=new THREE.PerspectiveCamera(60,320/200,0.1,100);camera.position.z=4;
const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setSize(320,200);
document.body.append(renderer.domElement);
const geometry=new THREE.BoxGeometry(1,1,1);
const material=new THREE.MeshBasicMaterial({color:0x174a8b});
const cube=new THREE.Mesh(geometry,material);scene.add(cube);
const width=480,height=240;
renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();
renderer.render(scene,camera);
